Generic Functions
In order to create a function that would allow us to summarize results, we want to know first how generic functions operate. The code below should help us to look at how a function like plot works.

plot.function

function (x, y = 0, to = 1, from = y, xlim = NULL, ylab = NULL, 
    ...) 
{
    if (!missing(y) && missing(from)) 
        from &lt;- y
    if (is.null(xlim)) {
        if (is.null(from)) 
            from &lt;- 0
    }
    else {
        if (missing(from)) 
            from &lt;- xlim[1L]
        if (missing(to)) 
            to &lt;- xlim[2L]
    }
    if (is.null(ylab)) {
        sx &lt;- substitute(x)
        ylab &lt;- if (mode(x) != "name") 
            deparse(sx)[1L]
        else {
            xname &lt;- list(...)[["xname"]]
            if (is.null(xname)) 
                xname &lt;- "x"
            paste0(sx, "(", xname, ")")
        }
    }
    curve(expr = x, from = from, to = to, xlim = xlim, ylab = ylab, 
        ...)
}
